	/*
     * @param	event CreateAttestationEvent
     */
    @EventHandler( payloadType=CreateAttestationEvent.class )
    public void handle( CreateAttestationEvent event) {
	    LOGGER.info("handling CreateAttestationEvent - " + event );
	    Attestation entity = new Attestation();
            entity.setAttestationId( event.getAttestationId() );
            entity.setStatement( event.getStatement() );
            entity.setAttestor( event.getAttestor() );
            entity.setDateSigned( event.getDateSigned() );
            entity.setResult( event.getResult() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAttestation( entity );
    }

    /*
     * @param	event UpdateAttestationEvent
     */
    @EventHandler( payloadType=UpdateAttestationEvent.class )
    public void handle( UpdateAttestationEvent event) {
    	LOGGER.info("handling UpdateAttestationEvent - " + event );
    	
	    Attestation entity = new Attestation();
            entity.setAttestationId( event.getAttestationId() );
            entity.setStatement( event.getStatement() );
            entity.setAttestor( event.getAttestor() );
            entity.setDateSigned( event.getDateSigned() );
            entity.setControl( event.getControl() );
            entity.setPolicy( event.getPolicy() );
            entity.setComplianceProgram( event.getComplianceProgram() );
            entity.setResult( event.getResult() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAttestation( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAttestation( entity );        
    }
    
