    /**
     * Method to retrieve the Attestation via an AttestationPrimaryKey.
     * @param 	id Long
     * @return 	Attestation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Attestation handle( FindAttestationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAttestationId() );
    }
    
    /**
     * Method to retrieve a collection of all Attestations
     *
     * @param	query	FindAllAttestationQuery 
     * @return 	List<Attestation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Attestation> handle( FindAllAttestationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAttestation,
 * but only if the id matches
 *
 * @param		entity	Attestation
 */
	protected void emitFindAttestation( Attestation entity ) {
		LOGGER.info("handling emitFindAttestation" );
		
	    queryUpdateEmitter.emit(FindAttestationQuery.class,
	                            query -> query.getFilter().getAttestationId().equals(entity.getAttestationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAttestation
	 * 
	 * @param		entity	Attestation
	 */
	protected void emitFindAllAttestation( Attestation entity ) {
		LOGGER.info("handling emitFindAllAttestation" );
		
	    queryUpdateEmitter.emit(FindAllAttestationQuery.class,
	                            query -> true,
	                            entity);
	}

